208	template <typename T> std::string SFAShape2String(const T &shape)
209	{
210	    std::ostringstream oss;
211	    oss << "[";
212	    if (shape.GetDimNum() > 0) {
213	        for (size_t i = 0; i < shape.GetDimNum() - 1; ++i) {
214	            oss << shape.GetDim(i) << ", ";
215	        }
216	        oss << shape.GetDim(shape.GetDimNum() - 1);
217	    }
218	    oss << "]";
219	    return oss.str();
220	}
