300	void SFAMlaTiling::CalcInnerSize(uint32_t s2Size)
301	{
302	    sInnerSize_ = 512; // 512:s2默认切分大小
303	    // FlashDecode时，如果S2的计算量>=256(确保切分后不小于128)但又不足以分2次计算时，则修改sInnerSize_，均分为2份进行计算，确保Nbuffer=2
304	    if (splitKVFlag_ && sfaInfo_->qLayout != SFALayout::TND) {
305	        if (s2Size == 256) { // 256:s2Size的阈值，判断sInnerSize_是否切分
306	            sInnerSize_ = 128; // 128:sInnerSize_值为s2Size的一半，均分为2份进行计算，
307	        } else if (s2Size > 256 && s2Size <= sInnerSize_) { // 256:s2Size的阈值，判断sInnerSize_是否切分
308	            sInnerSize_ = (sInnerSize_ + 1) / 2; // 2:减半
309	        }
310	    }
311	
312	    sInnerLoopTimes_ = (s2Size + sInnerSize_ - 1) / sInnerSize_;
313	    sInnerSizeTail_ = s2Size - (sInnerLoopTimes_ - 1) * sInnerSize_;
314	    if (sInnerSize_ > s2Size) {
315	        sInnerSize_ = s2Size;
316	    }
317	    sInnerSizeAlign_ = Align(sInnerSize_, BYTE_BLOCK); // 元素个数按照基本块大小对齐
318	
319	    CheckUbSpace();
320	}
