401	void SFAMlaTiling::NormalCalcFDWorkSpace(const uint32_t actCoreNum)
402	{
403	    if (splitKVFlag_) {
404	        uint32_t accumOutSize = 0;
405	        uint32_t logSumExpSize = 0;
406	        uint32_t FDParamNums = CalcBalanceFDParamNums(
407	            actCoreNum); // balanceModeFlag_ ? CalcBalanceFDParamNums(actCoreNum) : CalcUnbalanceFDParamNums();
408	        accumOutSize = FDParamNums * headDimAlign_;
409	        logSumExpSize =
410	            2 * FDParamNums * (BYTE_BLOCK / sfaInfo_->blockTypeSize); // log和sum的存储空间一致，共需要2份内存
411	        workspaceSize_ += (accumOutSize + logSumExpSize) * sfaInfo_->blockTypeSize;
412	        if (sfaInfo_->socVersion == platform_ascendc::SocVersion::ASCEND310P) {
413	            workspaceSize_ += static_cast<size_t>(actCoreNum) * 32; // 每个核SyncAll软同步需要32Byte记录状态
414	        }
415	    }
416	}
