423	void SFAMlaTiling::GetWorkspaceSize()
424	{
425	    uint32_t mmResElemSize = 4; // 4:fp32
426	    uint32_t vec1ResElemSize = 2; // 2:fp16/bf16
427	    uint32_t bmm2ResElemSize = 4; // 4:fp32
428	    uint32_t qPreProcResElemSize = 0; // 普通场景不涉及Q预处理
429	    uint32_t nUpdateElemSize = 4; // 4:int32
430	    uint32_t softmaxSumElemSize = 4; // 4:int32
431	    const float kvDtypeRatio = 1.0;
432	
433	    workspaceSize_ = libapiSize_;
434	    uint32_t preLoadNum = 1;
435	    uint32_t actCoreNum = coreNum_;
436	    preLoadNum = PRE_LOAD_NUM;
437	
438	    workspaceSize_ += preLoadNum * (mmResUbSize_ * actCoreNum * mmResElemSize);
439	    workspaceSize_ += preLoadNum * static_cast<size_t>(static_cast<float>(mmResUbSize_ * actCoreNum * vec1ResElemSize) *
440	                                                       kvDtypeRatio);
441	    workspaceSize_ += preLoadNum * bmm2ResUbSize_ * actCoreNum * bmm2ResElemSize;
442	    workspaceSize_ += preLoadNum * bmm2ResUbSize_ * actCoreNum * bmm2ResElemSize; // vec2ResGm
443	    workspaceSize_ +=
444	        preLoadNum *
445	        static_cast<size_t>(static_cast<float>(qPreSizeMla_ * actCoreNum * qPreProcResElemSize) * kvDtypeRatio);
446	    workspaceSize_ += preLoadNum * mBaseSize_ * actCoreNum * nUpdateElemSize;
447	    workspaceSize_ += preLoadNum * mBaseSize_ * actCoreNum * softmaxSumElemSize;
448	    // topk BlkSize == 1场景, 需要额外空间缓存离散聚合的值
449	    //              bufNum  s2Base   D   dRope  sizeOf(half)
450	    workspaceSize_ += 4 * 512 * (512 + 64) * 2 * actCoreNum; // 4:bufNum  512:s2Base  512:D  64:dRope  2:sizeOf(half)
451	    // 缓存有效mte2 size的长度 份数  512B对齐的长度  sizeof(int32_t)   aiv核数
452	    workspaceSize_ += 4 * 128 * 4 * (2 * actCoreNum); // 4:缓存有效mte2 size的长度 128:份数  4:512B对齐的长度  2:aiv核数
453	    CalcFDWorkSpace(actCoreNum);
454	}
