316	__aicore__ inline void
317	SparseFlashAttentionEnhanceMla<SFAT>::GetSparseActualSeqLen(uint32_t bIdx, uint32_t s1Idx, uint32_t n2Idx)
318	{
319	    if (tempLoopInfo.nextTokensPerBatch < 0 && s1Idx < (-tempLoopInfo.nextTokensPerBatch)) { // 存在行无效
320	        tempLoopInfo.curActualSeqLen = 0;
321	        return;
322	    }
323	    int64_t threshold = tempLoopInfo.curActualSeqLenOri;
324	    if (constInfo.sparseMode == 3) {
325	        threshold = static_cast<int64_t>(tempLoopInfo.nextTokensPerBatch) + s1Idx + 1;
326	    }
327	
328	    tempLoopInfo.curActualSeqLen = (constInfo.sparseBlockCount * constInfo.sparseBlockSize > threshold)
329	                                       ? threshold
330	                                       : constInfo.sparseBlockCount * constInfo.sparseBlockSize;
331	}
