334	__aicore__ inline uint32_t SparseFlashAttentionEnhanceMla<SFAT>::GetActualSeqLenKV(uint32_t bIdx)
335	{
336	    if constexpr (KV_LAYOUT_T == SFA_LAYOUT::TND) {
337	        if (bIdx > 0) {
338	            return actualSeqLengthsKVGm.GetValue(bIdx) - actualSeqLengthsKVGm.GetValue(bIdx - 1);
339	        } else if (bIdx == 0) {
340	            return actualSeqLengthsKVGm.GetValue(0);
341	        } else {
342	            return 0;
343	        }
344	    } else {
345	        if (constInfo.actualLenDimsKV == 0) {
346	            return constInfo.kvSeqSize;
347	        } else if (constInfo.actualLenDimsKV == 1) {
348	            return actualSeqLengthsKVGm.GetValue(0);
349	        } else {
350	            return actualSeqLengthsKVGm.GetValue(bIdx);
351	        }
352	    }
353	}
