525	template <typename SFAT> __aicore__ inline void SparseFlashAttentionEnhanceMla<SFAT>::InitCalcParamsEach()
526	{
527	    // 计算总的基本块
528	    uint32_t totalBaseNum = 0;
529	    uint32_t s1GBaseSize = constInfo.gSize;
530	    uint32_t actBatchS2 = 1;
531	    uint32_t coreNum = GetBlockNum();
532	    uint32_t currCoreIdx = aiCoreIdx;
533	    uint32_t actBatchS1 = 1;
534	    for (uint32_t bIdx = 0; bIdx < constInfo.batchSize; bIdx++) {
535	        uint32_t actBatchS1 = GetBalanceActualSeqLengths(actualSeqLengthsQGm, bIdx);
536	        if (actBatchS1 < constInfo.qSeqSize) {
537	            constInfo.needInit = true;
538	        }
539	        totalBaseNum += actBatchS1 * actBatchS2;
540	    }
541	    uint32_t avgBaseNum = 1;
542	    if (totalBaseNum > coreNum) {
543	        avgBaseNum = (totalBaseNum + coreNum - 1) / coreNum;
544	    } else {
545	        usedCoreNum = totalBaseNum;
546	    }
547	    if (aiCoreIdx >= usedCoreNum) {
548	        return;
549	    }
550		// 计算当前核的基本块
551		uint32_t accumBaseNum = 0;                       // 当前累积的基本块数
552	    uint32_t targetBaseNum = 0;
553	    uint32_t lastValidBIdx = 0;
554	    uint32_t lastValidactBatchS1 = 0;
555	    bool setStart = false;
556	    targetBaseNum = (currCoreIdx + 1) * avgBaseNum; // 计算当前的目标权重
557	    uint32_t targetStartBaseNum = targetBaseNum - avgBaseNum;
558	    for (uint32_t bN2Idx = 0; bN2Idx < constInfo.batchSize * constInfo.kvHeadNum; bN2Idx++) {
559	        uint32_t bIdx = bN2Idx / constInfo.kvHeadNum;
560	        actBatchS1 = GetBalanceActualSeqLengths(actualSeqLengthsQGm, bIdx);
561	        for (uint32_t s1GIdx = 0; s1GIdx < actBatchS1; s1GIdx++) {
562	            accumBaseNum += 1;
563	            if (!setStart && accumBaseNum >= targetStartBaseNum) {
564	                constInfo.bN2Start = bN2Idx;
565	                constInfo.gS1Start = s1GIdx;
566	                setStart = true;
567	            }
568	            if (accumBaseNum >= targetBaseNum) {
569	                // 更新当前核的End分核信息
570	                constInfo.bN2End = bN2Idx;
571	                constInfo.gS1End = s1GIdx;
572	                constInfo.s2End = 0;
573	                constInfo.coreStartKVSplitPos = 0;
574	                if (aiCoreIdx != 0) {
575	                    GetAxisStartIdx(constInfo.bN2Start, constInfo.gS1Start, 0);
576	                }
577	                return;
578	            }
579	        }
580	        if ((actBatchS1 > 0) && (actBatchS2 > 0)) {
581	            lastValidBIdx = bIdx;
582	            lastValidactBatchS1 = actBatchS1;
583	        }
584	    }
585	    if (!setStart) {
586	        constInfo.bN2Start = lastValidBIdx;
587	        constInfo.gS1Start = lastValidactBatchS1 - 1;
588	    }
589	    if (accumBaseNum < targetBaseNum) {
590	        // 更新最后一个核的End分核信息
591	        constInfo.bN2End = lastValidBIdx;
592	        constInfo.gS1End = lastValidactBatchS1 - 1;
593	        constInfo.s2End = 0;
594	        constInfo.coreStartKVSplitPos = 0;
595	        if (aiCoreIdx != 0) {
596	            GetAxisStartIdx(constInfo.bN2Start, constInfo.gS1Start, 0);
597	        }
598	        return;
599	    }
600	}
