620	__aicore__ inline void
621	SparseFlashAttentionEnhanceMla<SFAT>::CalcParams(uint32_t loop, uint64_t s2Start, uint32_t s2LoopIdx, RunInfo &info)
622	{
623	    info.loop = loop;
624	    info.bIdx = tempLoopInfo.bIdx;
625	    info.gS1Idx = tempLoopInfo.gS1Idx;
626	    info.s2Idx = s2LoopIdx;
627	    info.curSInnerLoopTimes = tempLoopInfo.s2LoopTimes;
628	
629	    info.tndIsS2SplitCore = tempLoopInfo.tndIsS2SplitCore;
630	    info.tndCoreStartKVSplitPos = tempLoopInfo.tndCoreStartKVSplitPos;
631	    info.isBmm2Output = false;
632	
633	    info.actS1Size = tempLoopInfo.actS1Size;
634	
635	    info.actMBaseSize = constInfo.mBaseSize;
636	    uint32_t remainedGS1Size = tempLoopInfo.actS1Size * constInfo.gSize - tempLoopInfo.gS1Idx;
637	    if (remainedGS1Size <= constInfo.mBaseSize && remainedGS1Size > 0) {
638	        info.actMBaseSize = tempLoopInfo.mBasicSizeTail;
639	    }
640	
641	    info.isValid = s2LoopIdx < tempLoopInfo.s2LoopTimes;
642	
643	    if ASCEND_IS_AIV {
644	        info.mSize = info.actMBaseSize;
645	        info.mSizeV = (info.mSize <= 16) ? info.mSize : (((info.mSize + 15) / 16 + 1) / 2 * 16);
646	        info.mSizeVStart = 0;
647	        if (tmpBlockIdx % 2 == 1) {
648	            info.mSizeVStart = info.mSizeV;
649	            info.mSizeV = info.mSize - info.mSizeV;
650	        }
651	    }
652	
653	    info.isChangeBatch = false;
654	
655	    info.isFirstSInnerLoop = s2LoopIdx == s2Start;
656	    if (info.isFirstSInnerLoop) {
657	        tempLoopInfo.bn2IdxInCurCore++;
658	    }
659	    info.isLastS2Loop = s2LoopIdx == tempLoopInfo.s2LoopTimes - 1;
660	    info.bn2IdxInCurCore = tempLoopInfo.bn2IdxInCurCore - 1;
661	    uint64_t actualSeqQPrefixSum;
662	    if constexpr (LAYOUT_T == SFA_LAYOUT::TND) {
663	        actualSeqQPrefixSum = (info.bIdx <= 0) ? 0 : actualSeqLengthsQGm.GetValue(info.bIdx - 1);
664	    } else {
665	        actualSeqQPrefixSum = (info.bIdx <= 0) ? 0 : info.bIdx * constInfo.qSeqSize;
666	    }
667	    info.tndBIdxOffsetForQ = actualSeqQPrefixSum * constInfo.qHeadNum * headDim;
668	
669	    uint64_t actualSeqKVPrefixSum;
670	    if constexpr (KV_LAYOUT_T == SFA_LAYOUT::TND) {
671	        actualSeqKVPrefixSum = (info.bIdx <= 0) ? 0 : actualSeqLengthsKVGm.GetValue(info.bIdx - 1);
672	    } else {
673	        actualSeqKVPrefixSum = (info.bIdx <= 0) ? 0 : info.bIdx * constInfo.kvSeqSize;
674	    }
675	    info.tndBIdxOffsetForKV = actualSeqKVPrefixSum * constInfo.kvHeadNum * headDim;
676	
677	    if (info.isFirstSInnerLoop) {
678	        uint64_t tndBIdxRopeOffsetForQ = actualSeqQPrefixSum * constInfo.qHeadNum * headDimRope;
679	        tensorACoreOffset = info.tndBIdxOffsetForQ + info.gS1Idx * headDim;
680	        tensorARopeCoreOffset = tndBIdxRopeOffsetForQ + info.gS1Idx * headDimRope;
681	
682	        uint64_t tndBIdxRopeOffsetForK = actualSeqKVPrefixSum * constInfo.kvHeadNum * headDimRope;
683	        tensorBCoreOffset = info.tndBIdxOffsetForKV + info.n2Idx * headDim;
684	        tensorBRopeCoreOffset = tndBIdxRopeOffsetForK + info.n2Idx * headDimRope;
685	        if (constInfo.sparseMode == 3) {
686	            threshold = static_cast<int64_t>(tempLoopInfo.nextTokensPerBatch) + info.gS1Idx / constInfo.gSize + 1;
687	        } else {
688	            threshold = tempLoopInfo.curActualSeqLenOri;
689	        }
690	        if constexpr (LAYOUT_T == SFA_LAYOUT::BSND) { // B,S1,N2 K
691	            topKBaseOffset = info.bIdx * constInfo.qSeqSize * constInfo.kvHeadNum * constInfo.sparseBlockCount +
692	                             info.gS1Idx / constInfo.gSize * constInfo.kvHeadNum * constInfo.sparseBlockCount +
693	                             info.n2Idx * constInfo.sparseBlockCount;
694	        } else if (LAYOUT_T == SFA_LAYOUT::TND) { // T N2 K
695	            topKBaseOffset = info.tndBIdxOffsetForQ / constInfo.gSize / constInfo.headDim * constInfo.kvHeadNum *
696	                                 constInfo.sparseBlockCount +
697	                             info.n2Idx * constInfo.sparseBlockCount +
698	                             info.gS1Idx / constInfo.gSize * constInfo.kvHeadNum * constInfo.sparseBlockCount;
699	        } else { // B N2 S1 K
700	            topKBaseOffset = info.bIdx * constInfo.kvHeadNum * constInfo.qSeqSize * constInfo.sparseBlockCount +
701	                             info.n2Idx * constInfo.qSeqSize * constInfo.sparseBlockCount +
702	                             info.gS1Idx / constInfo.gSize * constInfo.sparseBlockCount;
703	        }
704	    }
705	    info.topKBaseOffset = topKBaseOffset;
706	    info.threshold = threshold;
707	    info.tensorAOffset = tensorACoreOffset;
708	    info.tensorARopeOffset = tensorARopeCoreOffset;
709	    info.tensorBOffset = tensorBCoreOffset;
710	    info.tensorBRopeOffset = tensorBRopeCoreOffset;
