32	ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForSparseFlashAttentionGradEnhance(gert::TilingParseContext *context)
33	{
34	    OP_CHECK_IF(context == nullptr, OP_LOGE(context->GetNodeName(), "context is null."), return ge::GRAPH_FAILED);
35	    fe::PlatFormInfos *platformInfoPtr = context->GetPlatformInfo();
36	    OP_CHECK_IF(platformInfoPtr == nullptr,
37	                OP_LOGE(context->GetNodeName(), "platformInfoPtr is null."),
38	                return ge::GRAPH_FAILED);
39	
40	    auto compileInfoPtr = context->GetCompiledInfo<SparseFlashAttentionGradEnhanceCompileInfo>();
41	    OP_CHECK_IF(
42	        compileInfoPtr == nullptr, OP_LOGE(context->GetNodeName(), "compileInfoPtr is null."), return ge::GRAPH_FAILED);
43	
44	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
45	    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
46	    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
47	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
48	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
49	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, compileInfoPtr->l0aSize);
50	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, compileInfoPtr->l0bSize);
51	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0cSize);
52	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, compileInfoPtr->l2CacheSize);
53	
54	    OP_LOGI(context,
55	            "parse TilingParseContext succ. aivNum:%u, aicNum:%u, "
56	            "ubSize:%lu, l1Size:%lu, l0aSize:%lu, l0bSize:%lu, l0cSize:%lu, l2CacheSize:%lu",
57	            compileInfoPtr->aivNum,
58	            compileInfoPtr->aicNum,
59	            compileInfoPtr->ubSize,
60	            compileInfoPtr->l1Size,
61	            compileInfoPtr->l0aSize,
62	            compileInfoPtr->l0bSize,
63	            compileInfoPtr->l0cSize,
64	            compileInfoPtr->l2CacheSize);
65	
66	    return ge::GRAPH_SUCCESS;
67	}
