/*!
 * \file sparse_flash_attention_grad_enhance_tiling.cpp
 * \brief
 */

#include "sparse_flash_attention_grad_enhance_tiling.h"
#include <register/op_impl_registry.h>
#include "tiling_base/data_copy_transpose_tiling.h"
#include "tiling_base/tiling_templates_registry.h"

using namespace ge;
using namespace AscendC;

namespace optiling {
namespace sfage {

ASCENDC_EXTERN_C ge::graphStatus TilingSparseFlashAttentionGradEnhance(gert::TilingContext *context)
{
    return Ops::Transformer::OpTiling::TilingRegistry::GetInstance().DoTilingImpl(context);
}

ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForSparseFlashAttentionGradEnhance(gert::TilingParseContext *context)
{
    OP_CHECK_IF(context == nullptr, OP_LOGE(context->GetNodeName(), "context is null."), return ge::GRAPH_FAILED);
    fe::PlatFormInfos *platformInfoPtr = context->GetPlatformInfo();
    OP_CHECK_IF(platformInfoPtr == nullptr,
                OP_LOGE(context->GetNodeName(), "platformInfoPtr is null."),
                return ge::GRAPH_FAILED);

    auto compileInfoPtr = context->GetCompiledInfo<SparseFlashAttentionGradEnhanceCompileInfo>();
    OP_CHECK_IF(
        compileInfoPtr == nullptr, OP_LOGE(context->GetNodeName(), "compileInfoPtr is null."), return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, compileInfoPtr->l0aSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, compileInfoPtr->l0bSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0cSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, compileInfoPtr->l2CacheSize);

    OP_LOGI(context,
            "parse TilingParseContext succ. aivNum:%u, aicNum:%u, "
            "ubSize:%lu, l1Size:%lu, l0aSize:%lu, l0bSize:%lu, l0cSize:%lu, l2CacheSize:%lu",
            compileInfoPtr->aivNum,
            compileInfoPtr->aicNum,
            compileInfoPtr->ubSize,
            compileInfoPtr->l1Size,
            compileInfoPtr->l0aSize,
            compileInfoPtr->l0bSize,
            compileInfoPtr->l0cSize,
            compileInfoPtr->l2CacheSize);

    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(SparseFlashAttentionGradEnhance)
    .Tiling(TilingSparseFlashAttentionGradEnhance)
    .TilingParse<SparseFlashAttentionGradEnhanceCompileInfo>(
        TilingPrepareForSparseFlashAttentionGradEnhance); // 向框架注册入口函数
} // namespace sfage
} // namespace optiling

