432	    auto selected_block_count = indicesShape.GetDim(dimSize - 1);
433	
434	    auto selected_block_size =
435	        *context_->GetAttrs()->GetAttrPointer<int>(static_cast<size_t>(AttrIndex::SELECTED_BLOCK_SIZE));
436	    const size_t selectedBlockSizeValid[] = {1, 8, 16, 32, 64};
437	    uint32_t validnum = sizeof(selectedBlockSizeValid) / sizeof(selectedBlockSizeValid[0]);
438	    for (uint32_t i = 0; i < validnum; ++i) {
439	        if (selectedBlockSizeValid[i] == selected_block_size) {
440	            break;
441	        } else {
442	            if (i == validnum - 1) {
443	                OP_LOGE(context_, "Sparse_block_size only support 1/8/16/32/64,but got %d.", selected_block_size);
444	                return ge::GRAPH_FAILED;
445	            }
446	        }
447	    }
448	
449	    if (selected_block_size == 1) {
450	        if (selected_block_count > 8192) {
451	            OP_LOGE(context_,
452	                    "When sparse_block_size is 1, the maximum Topk token is 8192, but got %d.",
453	                    selected_block_count);
454	            return ge::GRAPH_FAILED;
455	        }
456	    } else {
457	        if (selected_block_count * selected_block_size > 16384) {
458	            OP_LOGE(
459	                context_, "The maximum Topk token is 16384, but got %d.", selected_block_size * selected_block_count);
460	            return ge::GRAPH_FAILED;
461	        }
462	    }
463	
464	    auto sparse_mode = *context_->GetAttrs()->GetAttrPointer<int>(static_cast<size_t>(AttrIndex::SPARSE_MODE));
465	    if (sparse_mode == 0) {
466	        tmpData.attenEnable = false;
467	    } else if (sparse_mode == 3) {
468	        OP_LOGI(context_, "SparseFlashAttentionGradEnhance AttenMask enable.");
469	        tmpData.attenEnable = true;
470	    } else {
471	        OP_LOGE(context_,
472	                "SparseFlashAttentionGradEnhance only support sparse_mode=0 or 3, now sparse_mode=%d.",
473	                sparse_mode);
474	        return ge::GRAPH_FAILED;
475	    }
476	
477	    if (dimDq != dimDk) {
478	        OP_LOGE(context_, "head_dim of Query[%ld] should be equal to head_dim of Key[%ld].", dimDq, dimDk);
479	        return ge::GRAPH_FAILED;
480	    }
481	    if (dimDq < dimDv) {
482	        OP_LOGE(context_, "head_dim of Query[%ld] can not less than head_dim of Value[%ld].", dimDq, dimDv);
483	        return ge::GRAPH_FAILED;
484	    }
485	    if (strcmp(inputLayout, TND_STR) != 0 && strcmp(inputLayout, BSND_STR) != 0) {
486	        OP_LOGE(context_,
487	                "SparseFlashAttentionGradEnhance only support TND or BSND layout, now layout is %s.",
488	                inputLayout);
489	        return ge::GRAPH_FAILED;
490	    }
491	    if (static_cast<size_t>(dimSize) != strlen(inputLayout)) {
492	        OP_LOGE(
493	            context_,
494	            "SparseFlashAttentionGradEnhance layout dims is not equal to the input's dim, now the query of dim is %u.",
495	            dimSize);
496	        return ge::GRAPH_FAILED;
497	    }
498	
499	    if (qRopeTensor != nullptr && kRopeTensor != nullptr) {
500	        OP_LOGD(context_, "SparseFlashAttentionGradEnhance qRope and kRope is not nullptr, rope is enabled.");
501	        tmpData.ropeEnable = true;
502	        const gert::Shape &qRopeShape =
503	            context_->GetOptionalInputTensor(static_cast<size_t>(InputIndex::Q_ROPE))->GetStorageShape();
504	        const gert::Shape &kRopeShape =
505	            context_->GetOptionalInputTensor(static_cast<size_t>(InputIndex::K_ROPE))->GetStorageShape();
506	        auto qRopeDim = qRopeShape.GetDim(dimSize - 1);
507	        auto kRopeDim = kRopeShape.GetDim(dimSize - 1);
508	        if (qRopeDim != kRopeDim) {
509	            OP_LOGE(context_, "SparseFlashAttentionGradEnhance headDim of qRope and kRope should be equal.");
510	            return ge::GRAPH_FAILED;
