515	        tmpData.ropeDim = 0;
516	        OP_LOGE(context_, "SparseFlashAttentionGradEnhance qRope and kRope should not be nullptr.");
517	        return ge::GRAPH_FAILED;
518	    }
519	
520	    if (strcmp(inputLayout, TND_STR) == 0) {
521	        const gert::Shape &actSeqQLenShape =
522	            context_->GetOptionalInputTensor(static_cast<size_t>(InputIndex::ACTUAL_SEQ_Q_LEN))->GetStorageShape();
523	        tmpData.b = actSeqQLenShape.GetDim(DIM_0);
524	        tmpData.t1 = queryShape.GetDim(DIM_0);
525	        tmpData.t2 = keyShape.GetDim(DIM_0);
526	        tmpData.s1 = tmpData.t1;
527	        tmpData.s2 = tmpData.t2;
528	        tmpData.n2 = keyShape.GetDim(DIM_1);
529	        OP_CHECK_IF(tmpData.n2 == 0, OP_LOGE(context_, "key headNum is 0"), return ge::GRAPH_FAILED);
530	        tmpData.g = queryShape.GetDim(DIM_1) / tmpData.n2;
531	        tmpData.layout = static_cast<uint32_t>(InputLayout::TND);
532	    } else { // BSND
533	        tmpData.b = queryShape.GetDim(DIM_0);
534	        tmpData.s1 = queryShape.GetDim(DIM_1);
535	        tmpData.s2 = keyShape.GetDim(DIM_1);
536	        tmpData.n2 = keyShape.GetDim(DIM_2);
537	        OP_CHECK_IF(tmpData.n2 == 0, OP_LOGE(context_, "key headNum is 0"), return ge::GRAPH_FAILED);
538	        tmpData.g = queryShape.GetDim(DIM_2) / tmpData.n2;
539	        tmpData.layout = static_cast<uint32_t>(InputLayout::BSND);
540	    }
541	
542	    if (tmpData.g <= 0) {
543	        OP_LOGE(context_, "g (N1 / N2) should be larger than 0, but got g=%ld.", tmpData.g);
544	        return ge::GRAPH_FAILED;
545	    }
546	
547	    int64_t n1 = tmpData.n2 * tmpData.g;
548	    int64_t divided = (n1) % 3 == 0 ? (n1 / 3) : n1;
549	    if (tmpData.n2 != 1 || n1 > 128 || (divided & (divided - 1)) != 0) {
550	        OP_LOGE(context_,
551	                "SparseFlashAttentionGrad only support n2=1 and n1=1/2/3/4//6/8/12/16/24/32/48/64/96/128, "
552	                "but got n2=%ld n1=%ld.",
553	                tmpData.n2,
554	                n1);
555	        return ge::GRAPH_FAILED;
556	    }
557	
558	    tilingData.opInfo.set_B(tmpData.b);
559	    tilingData.opInfo.set_G(tmpData.g);
560	    OP_CHECK_IF(tilingData.opInfo.get_G() == 0, OP_LOGE(context_, "g is 0"), return ge::GRAPH_FAILED);
561	    tilingData.opInfo.set_N2(tmpData.n2);
562	    tilingData.opInfo.set_S1(tmpData.s1);
563	    tilingData.opInfo.set_S2(tmpData.s2);
564	    tilingData.opInfo.set_D(dimDq);
565	    tilingData.opInfo.set_D2(dimDv);
566	    tilingData.opInfo.set_ropeD(tmpData.ropeDim);
567	    tilingData.opInfo.set_layout(tmpData.layout);
568	    tilingData.opInfo.set_scaleValue(
569	        *context_->GetAttrs()->GetAttrPointer<float>(static_cast<size_t>(AttrIndex::SCALE_VALUE)));
570	    tilingData.opInfo.set_selectedBlockCount(selected_block_count);
571	    tilingData.opInfo.set_selectedBlockSize(selected_block_size);
572	    bool deterministic = *context_->GetAttrs()->GetAttrPointer<bool>(static_cast<size_t>(AttrIndex::DETERMINISTIC));
573	
574	    tmpData.d = tilingData.opInfo.get_D();
575	    tmpData.d2 = tilingData.opInfo.get_D2();
576	    tmpData.dataTypeSize = B32;
577	    tmpData.queryType =
578	        static_cast<uint32_t>(context_->GetInputDesc(static_cast<size_t>(InputIndex::QUERY))->GetDataType());
579	    tmpData.selected_block_count = selected_block_count;
580	    tmpData.selected_block_size = selected_block_size;
581	    tmpData.deterministic = deterministic;
582	
583	    std::vector<uint32_t> DTYPE_SUPPORT_MAP = {static_cast<uint32_t>(ge::DT_FLOAT16),
584	                                               static_cast<uint32_t>(ge::DT_BF16)};
585	    OP_CHECK_IF(std::find(DTYPE_SUPPORT_MAP.begin(), DTYPE_SUPPORT_MAP.end(), tmpData.queryType) ==
586	                    DTYPE_SUPPORT_MAP.end(),
587	                OP_LOGE(context_, "Query type only support DT_FLOAT16 and DT_BF16"),
588	                return ge::GRAPH_FAILED);
589	
590	    auto ret = CheckDtypeValid(context_);
591	    if (ret != ge::GRAPH_SUCCESS) {
592	        OP_LOGE(context_, "SparseFlashAttentionGradEnhance the dtype of input is invalid.");
593	        return ge::GRAPH_FAILED;
594	    }
595	
596	    if (tmpData.layout == static_cast<uint32_t>(InputLayout::TND)) {
597	        ret = CheckTndShapeValid(context_, tmpData.t1, tmpData.n2 * tmpData.g, tmpData.d, tmpData.d2, tmpData.n2);
598	    }
599	
600	    if (ret != ge::GRAPH_SUCCESS) {
601	        OP_LOGE(context_, "SparseFlashAttentionGradEnhance the input shpae of TND Layout is invalid.");
602	        return ge::GRAPH_FAILED;
603	    }
604	
605	    return ge::GRAPH_SUCCESS;
606	}
